package com.bplus.share;
import android.content.*;import android.net.*;import android.os.*;import java.net.*;import java.util.*;
/** Wi-Fi network with IPv4, or an UP Wi-Fi/AP interface with IPv4. Cellular/VPN alone never qualifies. */
public final class LocalNetwork{
 public static boolean usable(Context c){try{ConnectivityManager cm=c.getSystemService(ConnectivityManager.class);for(Network n:cm.getAllNetworks()){NetworkCapabilities cap=cm.getNetworkCapabilities(n);if(cap==null||!cap.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)||cap.hasTransport(NetworkCapabilities.TRANSPORT_VPN))continue;LinkProperties lp=cm.getLinkProperties(n);if(lp!=null)for(LinkAddress a:lp.getLinkAddresses())if(valid(a.getAddress()))return true;}}catch(Exception ignored){}try{Enumeration<NetworkInterface> all=NetworkInterface.getNetworkInterfaces();while(all.hasMoreElements()){NetworkInterface ni=all.nextElement();String name=ni.getName().toLowerCase(java.util.Locale.ROOT);if(!ni.isUp()||!(name.startsWith("wlan")||name.startsWith("wifi")||name.startsWith("ap")||name.startsWith("swlan")||name.startsWith("softap")))continue;Enumeration<InetAddress> addresses=ni.getInetAddresses();while(addresses.hasMoreElements())if(valid(addresses.nextElement()))return true;}}catch(Exception ignored){}return false;}
 private static boolean valid(InetAddress a){return a instanceof Inet4Address&&!a.isLoopbackAddress()&&!a.isLinkLocalAddress()&&!a.isAnyLocalAddress();}
 public static void watch(Context c){Handler h=new Handler(Looper.getMainLooper());Runnable refresh=()->{if(usable(c)){if(TransferService.get()==null)try{TransferService.start(c);}catch(Exception ignored){}}else{c.stopService(new Intent(c,TransferService.class));c.getSystemService(android.app.NotificationManager.class).cancel(1);}};try{ConnectivityManager cm=c.getSystemService(ConnectivityManager.class);cm.registerNetworkCallback(new NetworkRequest.Builder().clearCapabilities().build(),new ConnectivityManager.NetworkCallback(){public void onAvailable(Network n){h.post(refresh);}public void onLost(Network n){h.post(refresh);}public void onLinkPropertiesChanged(Network n,LinkProperties p){h.post(refresh);}public void onCapabilitiesChanged(Network n,NetworkCapabilities p){h.post(refresh);}});}catch(Exception ignored){}IntentFilter f=new IntentFilter();f.addAction("android.net.wifi.WIFI_AP_STATE_CHANGED");f.addAction("android.net.wifi.STATE_CHANGE");f.addAction("android.net.conn.CONNECTIVITY_CHANGE");try{BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context x,Intent i){h.postDelayed(refresh,500);}};if(Build.VERSION.SDK_INT>=33)c.registerReceiver(receiver,f,Context.RECEIVER_NOT_EXPORTED);else c.registerReceiver(receiver,f);}catch(Exception ignored){}h.post(new Runnable(){public void run(){refresh.run();h.postDelayed(this,3000);}});}
}
